callGraph.callee:
messagesToSummarize
      .map((m) => {
        const prefix =
          m.role === "user"
            ? "User"
            : m.role === "assistant"
              ? "Assistant"
              : "System";
        return `[${prefix}]\n${m.content}`;
      })
      .join

protectedIndices
      .filter((i) => i < history.length - 1 && !evictSet.has(i))
      .flatMap((i) => {
        const msg = history[i];
        if (!msg) return [];
        return [
          {
            idx: i,
            cost: msgCost(msg),
            score: messagePriorityScore(msg, i, history.length),
          },
        ];
      })
      .sort
